+}
+
+// A regenerating command that does not finish within regenerateLimit leaves the generated file
+// kept: its full text stays in the review source, its outcome is kept and no finding claims a
+// mismatch, because its output was never checked.
+func TestReviewInPartsKeepsAGeneratedFileWhoseRegenerationTimesOut(t *testing.T) {
+	old := regenerateLimit
+	regenerateLimit = 300 * time.Millisecond
+	t.Cleanup(func() { regenerateLimit = old })
+	r := newEdgeRepo(t)
+	r.write("notes.txt", "start\n")
+	start := r.commit("start", nil)
+	slow := "# Code generated by exec sleep 30; DO NOT EDIT.\n" + strings.Repeat("srow\n", 2000)
+	r.write("data/slow.csv", slow)
+	r.write("big.txt", exactly(reviewCeiling+20000, "b"))
+	r.commit("candidate", nil)
+	began := time.Now()
+	x, _, dir, res, err := wideReview(t, r, start)
+	if took := time.Since(began); took > 20*time.Second {
+		t.Errorf("the review took %v, so the blocking command was not stopped at the limit", took)
+	}
+	if err != nil || res.Record.Verdict != "approve" || len(res.Record.Findings) != 0 {
+		t.Fatalf("the review is %q with findings %v, %v", res.Record.Verdict, res.Record.Findings, err)
+	}
+	var sent strings.Builder
+	for _, b := range x.briefs {
+		sent.WriteString(b.Dynamic)
 	}
+	for _, want := range []string{"--- data/slow.csv (added; mode 100644)\n", "srow\nsrow\nsrow\n"} {
+		if !strings.Contains(sent.String(), want) {
+			t.Errorf("the parts do not carry %q", want)
+		}
+	}
+	raw, err := os.ReadFile(filepath.Join(dir, "executor-review", "review-1-material.json"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var ev Material
+	if err := json.Unmarshal(raw, &ev); err != nil {
+		t.Fatal(err)
+	}
+	want := []GeneratedFile{{Path: "data/slow.csv", Command: "exec sleep 30", SHA256: core.HashHex([]byte(slow)), Outcome: "kept"}}
+	if fmt.Sprint(ev.Generated) != fmt.Sprint(want) {
+		t.Errorf("the evidence records %v, want %v", ev.Generated, want)
+	}
+	source, err := os.ReadFile(filepath.Join(dir, "executor-review", "review-1-source.txt"))
+	if err != nil || !strings.Contains(string(source), slow[len("# Code generated by exec sleep 30; DO NOT EDIT.\n"):]) {
+		t.Errorf("the retained source does not carry the full text of the generated file: %v", err)
+	}
 }

